<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue';import {useRoute} from 'vue-router';import {http,dataOf} from '../api/http';import {ElMessage,ElMessageBox} from 'element-plus'
import {stepUpHeader,withStepUp} from '../api/stepUp'
import {useAuthStore} from '../stores/auth'
const route=useRoute(),auth=useAuthStore(),canManage=computed(()=>auth.can('integration:manage')),canRetry=computed(()=>auth.can('integration:retry')),activeTab=ref('systems')
const rows=ref<any[]>([]),jobs=ref<any[]>([]),deadLetters=ref<any[]>([]),loading=ref(false),dialog=ref(false),editingId=ref<number|null>(null),mappingDialog=ref(false),mappingId=ref(0),mappingVersion=ref(1),mappingText=ref('[]')
const form=reactive({systemCode:'',systemName:'',systemType:'MES',baseUrl:'',authType:'HMAC',secret:'',active:true,ipWhitelist:'',oauthIntrospectionUrl:'',oauthClientId:'',oauthRequiredScopes:'rdp.webhook',oauthAudience:'',oauthIssuer:'',oauthSourceClientId:'',oauthTimeoutMillis:3000,trustDomain:'',entityType:'',cursorField:'',cursorType:'NUMBER',recordKeyField:'',sourceVersionField:'',sourcePriority:0,conflictPolicy:'PRIORITY_THEN_VERSION',deliveryMode:'NONE',deliveryUrl:'',deliveryTimeoutMillis:5000,maxRetries:3,retryDelays:'60,300,1800',version:null as number|null})
async function load(){loading.value=true;try{const [configs,jobRows,letters]=await Promise.all([http.get('/integrations'),http.get('/integrations/jobs'),http.get('/integrations/dead-letters')]);rows.value=dataOf(configs);jobs.value=dataOf(jobRows);deadLetters.value=dataOf(letters)}finally{loading.value=false}}
function reset(){Object.assign(form,{systemCode:'',systemName:'',systemType:'MES',baseUrl:'',authType:'HMAC',secret:'',active:true,ipWhitelist:'',oauthIntrospectionUrl:'',oauthClientId:'',oauthRequiredScopes:'rdp.webhook',oauthAudience:'',oauthIssuer:'',oauthSourceClientId:'',oauthTimeoutMillis:3000,trustDomain:'',entityType:'',cursorField:'',cursorType:'NUMBER',recordKeyField:'',sourceVersionField:'',sourcePriority:0,conflictPolicy:'PRIORITY_THEN_VERSION',deliveryMode:'NONE',deliveryUrl:'',deliveryTimeoutMillis:5000,maxRetries:3,retryDelays:'60,300,1800',version:null})}
function create(){editingId.value=null;reset();dialog.value=true}
function edit(row:any){const config=row.config||{};editingId.value=row.id;Object.assign(form,{systemCode:row.systemCode,systemName:row.systemName,systemType:row.systemType,baseUrl:row.baseUrl||'',authType:row.authType,secret:'',active:row.active,ipWhitelist:(config.ipWhitelist||[]).join(','),oauthIntrospectionUrl:config.oauthIntrospectionUrl||'',oauthClientId:config.oauthClientId||'',oauthRequiredScopes:(config.oauthRequiredScopes||['rdp.webhook']).join(' '),oauthAudience:config.oauthAudience||'',oauthIssuer:config.oauthIssuer||'',oauthSourceClientId:config.oauthSourceClientId||'',oauthTimeoutMillis:config.oauthTimeoutMillis||3000,trustDomain:config.trustDomain||'',entityType:config.entityType||'',cursorField:config.cursorField||'',cursorType:config.cursorType||'NUMBER',recordKeyField:config.recordKeyField||'',sourceVersionField:config.sourceVersionField||'',sourcePriority:config.sourcePriority||0,conflictPolicy:config.conflictPolicy||'PRIORITY_THEN_VERSION',deliveryMode:config.deliveryMode||'NONE',deliveryUrl:config.deliveryUrl||'',deliveryTimeoutMillis:config.deliveryTimeoutMillis||5000,maxRetries:config.maxRetries||3,retryDelays:(config.retryDelaysSeconds||[60,300,1800]).join(','),version:row.version});dialog.value=true}
function authTypeChanged(value:string){if(value==='OAUTH2'&&form.deliveryMode==='HTTP')form.deliveryMode='NONE'}
function generateHmacSecret(){const bytes=new Uint8Array(32);crypto.getRandomValues(bytes);form.secret=btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');ElMessage.success('已在浏览器内生成 256 位随机密钥，请通过安全渠道交付给外部系统')}
async function save(){const ipWhitelist=form.ipWhitelist.split(',').map(v=>v.trim()).filter(Boolean);if(!ipWhitelist.length){ElMessage.error('外部写入配置必须至少填写一个精确 IP 白名单');return}if(form.authType==='HMAC'&&form.secret&&new TextEncoder().encode(form.secret).length<32){ElMessage.error('HMAC 共享密钥至少需要 32 个 UTF-8 字节');return}if(form.authType==='OAUTH2'&&![form.oauthIntrospectionUrl,form.oauthClientId,form.oauthRequiredScopes,form.oauthAudience,form.oauthIssuer,form.oauthSourceClientId].every(v=>String(v).trim())){ElMessage.error('OAuth2 自省地址、两类客户端身份、scope、audience 和 issuer 均为必填');return}const retryDelaysSeconds=form.retryDelays.split(',').map(v=>Number(v.trim())).filter(v=>Number.isInteger(v));const config:any={ipWhitelist,cursorType:form.cursorType,sourcePriority:form.sourcePriority,conflictPolicy:form.conflictPolicy,deliveryMode:form.deliveryMode,deliveryTimeoutMillis:form.deliveryTimeoutMillis,maxRetries:form.maxRetries,retryDelaysSeconds};if(form.authType==='OAUTH2'){config.oauthIntrospectionUrl=form.oauthIntrospectionUrl.trim();config.oauthClientId=form.oauthClientId.trim();config.oauthRequiredScopes=form.oauthRequiredScopes.split(/\s+/).map(v=>v.trim()).filter(Boolean);config.oauthTimeoutMillis=form.oauthTimeoutMillis;config.oauthAudience=form.oauthAudience.trim();config.oauthIssuer=form.oauthIssuer.trim();config.oauthSourceClientId=form.oauthSourceClientId.trim()}if(form.trustDomain)config.trustDomain=form.trustDomain.trim().toUpperCase();if(form.entityType)config.entityType=form.entityType.trim().toUpperCase();if(form.cursorField)config.cursorField=form.cursorField.trim();if(form.recordKeyField)config.recordKeyField=form.recordKeyField.trim();if(form.sourceVersionField)config.sourceVersionField=form.sourceVersionField.trim();if(form.deliveryMode==='HTTP')config.deliveryUrl=form.deliveryUrl.trim();const body={systemCode:form.systemCode,systemName:form.systemName,systemType:form.systemType,baseUrl:form.baseUrl||null,authType:form.authType,secret:form.secret||null,active:form.active,config,expectedVersion:form.version};if(editingId.value)await http.put(`/integrations/${editingId.value}`,body);else await http.post('/integrations',body);ElMessage.success('集成配置已保存');dialog.value=false;await load()}
async function mappings(row:any){mappingId.value=row.id;mappingVersion.value=row.mappingVersion;mappingText.value=JSON.stringify(dataOf(await http.get(`/integrations/${row.id}/mappings`)),null,2);mappingDialog.value=true}
async function saveMappings(){try{const parsed=JSON.parse(mappingText.value);if(!Array.isArray(parsed))throw new Error();await http.put(`/integrations/${mappingId.value}/mappings?expectedMappingVersion=${mappingVersion.value}`,parsed.map(({sourceField,targetField,transformation,required,defaultValue}:any)=>({sourceField,targetField,transformation,required,defaultValue})));ElMessage.success('字段映射已保存');mappingDialog.value=false;await load()}catch(error){if(error instanceof SyntaxError)ElMessage.error('映射 JSON 格式不正确')}}
async function retry(row:any){const {value}=await ElMessageBox.prompt(row.localCommitted?'事件已完成本地信任裁决；将保留业务载荷与裁决结果，仅刷新当前HTTP交付地址、超时和退避配置后排队。':'请输入本次人工重放说明；将显式采用当前映射版本，原接收快照仍保留。','重放死信',{inputValue:row.localCommitted?'核对并更新远端适配器配置后重试交付':'核对并修正映射后人工重放',inputPattern:/\S+/,inputErrorMessage:'必须填写处置说明'});const endpoint=`/integrations/dead-letters/${row.id}/retry`,body={note:value,useCurrentMapping:true};await withStepUp({purpose:'PRIVILEGE',method:'POST',target:endpoint,label:`重放集成死信 #${row.id}`,payload:body},proof=>http.post(endpoint,body,{headers:stepUpHeader(proof)}));ElMessage.success('死信已进入后台重放队列');await load()}
async function reconcile(row:any){const result:any=dataOf(await http.post(`/integrations/${row.id}/reconcile`));ElMessage.success(`对账完成：匹配 ${result.matched}，缺失 ${result.missing}，摘要异常 ${result.digestMismatch}`)}
function statusType(status:string){return status==='COMPLETED'||status==='RESOLVED'?'success':status==='FAILED'||status==='MANUAL_REVIEW'?'danger':status==='SKIPPED'?'warning':'info'}
function syncRouteTab(){activeTab.value=route.path.includes('/mappings')?'mappings':'systems'}
watch(()=>route.path,syncRouteTab);onMounted(()=>{syncRouteTab();load()})
</script>
<template><div class="page"><div class="page-head"><div><h1 class="page-title">系统集成</h1><div class="page-subtitle">持久接收、确定性映射、信任源裁决、事务游标、指数退避与死信补偿</div></div><el-button v-if="canManage" type="primary" @click="create">新增配置</el-button></div>
 <el-alert title="接入支持 HMAC 与 OAuth2 RFC 7662 令牌自省；HTTP交付和OAuth2自省均必须由部署方配置精确主机白名单，生产默认仅允许HTTPS公网目标。真实 MES / PLM / ERP 字段、账号、网络白名单和回写规则仍须取得厂商资料后联调。" type="warning" :closable="false" show-icon/>
 <el-tabs v-model="activeTab" class="integration-tabs"><el-tab-pane label="接入配置" name="systems"><div class="surface"><el-table :data="rows" v-loading="loading"><el-table-column prop="systemCode" label="系统编码"/><el-table-column prop="systemName" label="名称"/><el-table-column prop="systemType" label="类型" width="90"/><el-table-column label="游标" min-width="150"><template #default="{row}">{{row.syncCursor||'尚未推进'}} / v{{row.mappingVersion}}</template></el-table-column><el-table-column prop="authType" label="认证" width="90"/><el-table-column label="密钥" width="90"><template #default="{row}"><el-tag :type="row.secretConfigured?'success':'danger'">{{row.secretConfigured?'已配置':'未配置'}}</el-tag></template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{row.active?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="230"><template #default="{row}"><el-button v-if="canManage" link type="primary" @click="edit(row)">编辑</el-button><el-button link @click="mappings(row)">字段映射</el-button><el-button v-if="canManage" link @click="reconcile(row)">对账</el-button></template></el-table-column></el-table></div></el-tab-pane>
 <el-tab-pane label="API 与字段映射" name="mappings"><div class="mapping-grid"><article v-for="row in rows" :key="row.id" class="surface mapping-card"><small>{{row.systemType}} · MAPPING v{{row.mappingVersion}}</small><h3>{{row.systemName}}</h3><p>{{row.systemCode}} · {{row.authType}} · 游标 {{row.syncCursor||'未推进'}}</p><div><span>外部业务字段</span><i>→</i><b>平台标准字段</b></div><el-button type="primary" plain @click="mappings(row)">打开真实映射配置</el-button></article></div></el-tab-pane>
 <el-tab-pane label="接入作业" name="jobs"><div class="surface"><el-table :data="jobs"><el-table-column prop="id" label="作业" width="75"/><el-table-column prop="systemCode" label="系统"/><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="statusType(row.status)">{{row.status}}</el-tag></template></el-table-column><el-table-column prop="idempotencyKey" label="幂等键" min-width="170"/><el-table-column prop="mappingVersion" label="映射版本" width="90"/><el-table-column prop="cursorValue" label="游标" width="110"/><el-table-column prop="attemptCount" label="尝试" width="70"/><el-table-column prop="errorMessage" label="错误" min-width="200" show-overflow-tooltip/><el-table-column prop="startedTime" label="开始时间" width="180"/></el-table></div></el-tab-pane>
 <el-tab-pane label="死信与重放" name="dead"><div class="surface"><el-table :data="deadLetters"><el-table-column prop="id" label="死信" width="75"/><el-table-column prop="systemCode" label="系统"/><el-table-column prop="eventKey" label="事件键" min-width="170"/><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="statusType(row.status)">{{row.status}}</el-tag></template></el-table-column><el-table-column prop="retryCount" label="重试" width="70"/><el-table-column prop="errorMessage" label="脱敏错误" min-width="240" show-overflow-tooltip/><el-table-column prop="nextRetryTime" label="下次自动重试" width="180"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button v-if="canRetry&&['PENDING','MANUAL_REVIEW'].includes(row.status)" link type="primary" @click="retry(row)">人工重放</el-button></template></el-table-column></el-table></div></el-tab-pane></el-tabs>
 <el-dialog v-model="dialog" :title="editingId?'编辑集成配置':'新增集成配置'" width="720"><el-form label-position="top"><div class="two"><el-form-item label="系统编码"><el-input v-model="form.systemCode" placeholder="MES_MAIN"/></el-form-item><el-form-item label="系统名称"><el-input v-model="form.systemName"/></el-form-item></div><div class="two"><el-form-item label="系统类型"><el-select v-model="form.systemType"><el-option v-for="v in ['MES','PLM','ERP','DEVICE','OTHER']" :key="v" :label="v" :value="v"/></el-select></el-form-item><el-form-item label="认证方式"><el-select v-model="form.authType" @change="authTypeChanged"><el-option label="HMAC-SHA256" value="HMAC"/><el-option label="OAuth2 RFC 7662" value="OAUTH2"/></el-select></el-form-item></div><el-form-item label="服务地址"><el-input v-model="form.baseUrl" placeholder="https://mes.example/api"/></el-form-item><el-form-item :label="form.authType==='OAUTH2'?'自省端客户端密钥':'HMAC 共享密钥'"><el-input v-model="form.secret" type="password" show-password :placeholder="editingId?'留空则保持原密钥':'新配置必填'"/><div v-if="form.authType==='HMAC'" class="form-tip">至少 32 个 UTF-8 字节；建议使用 256 位随机值。<el-button link type="primary" @click="generateHmacSecret">生成强密钥</el-button></div></el-form-item><div v-if="form.authType==='OAUTH2'" class="oauth-box"><el-form-item label="令牌自省地址（必填）"><el-input v-model="form.oauthIntrospectionUrl" placeholder="https://idp.example/oauth2/introspect"/><div class="form-tip">必须由部署方加入精确主机白名单；生产默认拒绝HTTP与私网解析结果。</div></el-form-item><div class="two"><el-form-item label="自省端客户端 ID（必填）"><el-input v-model="form.oauthClientId"/><div class="form-tip">仅用于本平台访问自省端，不等于外部调用方 AppID。</div></el-form-item><el-form-item label="自省超时（毫秒）"><el-input-number v-model="form.oauthTimeoutMillis" :min="100" :max="5000"/></el-form-item></div><el-form-item label="必需 scopes（必填，空格分隔）"><el-input v-model="form.oauthRequiredScopes" placeholder="rdp.webhook"/></el-form-item><div class="two"><el-form-item label="目标 audience（必填）"><el-input v-model="form.oauthAudience"/></el-form-item><el-form-item label="外部调用方 AppID / client_id（必填）"><el-input v-model="form.oauthSourceClientId"/><div class="form-tip">每个外部系统必须使用独立调用身份。</div></el-form-item></div><el-form-item label="令牌 issuer（必填）"><el-input v-model="form.oauthIssuer" placeholder="https://idp.example/"/></el-form-item></div><el-form-item label="IP 白名单（必填）"><el-input v-model="form.ipWhitelist" placeholder="10.0.0.10, 10.0.0.11"/></el-form-item><div class="two"><el-form-item label="信任域"><el-input v-model="form.trustDomain" placeholder="MANUFACTURING_ORDER"/></el-form-item><el-form-item label="实体类型"><el-input v-model="form.entityType" placeholder="WORK_ORDER"/></el-form-item></div><div class="two"><el-form-item label="增量游标字段（源路径）"><el-input v-model="form.cursorField" placeholder="sequence"/></el-form-item><el-form-item label="游标类型"><el-select v-model="form.cursorType"><el-option label="数值" value="NUMBER"/><el-option label="时间戳" value="INSTANT"/><el-option label="字符串" value="LEXICOGRAPHIC"/></el-select></el-form-item></div><div class="two"><el-form-item label="业务主键字段（源路径）"><el-input v-model="form.recordKeyField" placeholder="workOrder.id"/></el-form-item><el-form-item label="来源版本字段"><el-input v-model="form.sourceVersionField" placeholder="version"/></el-form-item></div><div class="two"><el-form-item label="信任源优先级"><el-input-number v-model="form.sourcePriority" :min="0" :max="10000"/></el-form-item><el-form-item label="冲突规则"><el-select v-model="form.conflictPolicy"><el-option label="优先级后版本" value="PRIORITY_THEN_VERSION"/><el-option label="仅优先级" value="PRIORITY_ONLY"/><el-option label="仅版本" value="VERSION_ONLY"/></el-select></el-form-item></div><div class="two"><el-form-item label="规范载荷交付"><el-select v-model="form.deliveryMode"><el-option label="不调用远端" value="NONE"/><el-option label="HTTP POST（带幂等键与HMAC）" value="HTTP" :disabled="form.authType!=='HMAC'"/></el-select></el-form-item><el-form-item label="交付超时（毫秒）"><el-input-number v-model="form.deliveryTimeoutMillis" :min="100" :max="30000"/></el-form-item></div><el-form-item v-if="form.deliveryMode==='HTTP'" label="HTTP 交付地址"><el-input v-model="form.deliveryUrl" placeholder="https://adapter.example/events"/><div class="form-tip">远端必须按 X-Idempotency-Key 幂等处理；503/超时将进入退避重试。</div></el-form-item><div class="two"><el-form-item label="最大自动重试次数"><el-input-number v-model="form.maxRetries" :min="1" :max="10"/></el-form-item><el-form-item label="退避秒数（默认1/5/30分钟）"><el-input v-model="form.retryDelays" placeholder="60,300,1800"/></el-form-item></div><el-switch v-model="form.active" active-text="启用接入"/></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
 <el-dialog v-model="mappingDialog" title="字段映射 JSON" width="720"><el-alert title="转换支持 DIRECT / TRIM / UPPERCASE / LOWERCASE / NUMBER / DATE / CONSTANT / UNIT；UNIT 的 defaultValue 是换算系数。保存后在途作业仍使用接收时快照。" type="info" :closable="false"/><el-input v-model="mappingText" type="textarea" :rows="16" class="mono" :readonly="!canManage"/><template #footer><el-button @click="mappingDialog=false">关闭</el-button><el-button v-if="canManage" type="primary" @click="saveMappings">保存映射</el-button></template></el-dialog>
</div></template>
<style scoped>.integration-tabs{margin-top:16px}.two{display:grid;grid-template-columns:1fr 1fr;gap:15px}.oauth-box{margin:8px 0 18px;padding:16px;border:1px solid var(--el-border-color);border-radius:10px;background:var(--el-fill-color-lighter)}.mapping-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.mapping-card{padding:20px}.mapping-card small{font:9px monospace;color:#4ba9c7}.mapping-card h3{font-size:14px;color:#d5ecf7;margin:8px 0}.mapping-card p{font-size:10px;color:#617f98}.mapping-card>div{display:flex;align-items:center;gap:10px;margin:18px 0;font-size:10px;color:#68869d}.mapping-card i{font-style:normal;color:#48ddfb;text-shadow:0 0 8px #48ddfb}.mapping-card b{color:#afd8e7}@media(max-width:800px){.mapping-grid{grid-template-columns:1fr}}</style>
